import React, { useState } from 'react';
import { useItinerario, useClima, useToast } from '../../hooks';
import { MENSAGENS } from '../../utils';

const SeccaoItinerario = ({ 
  mostrarItinerario, setMostrarItinerario, setMostrarMembros, setMostrarAcertos, 
  setMostrarChecklist, setMostrarMapa, setMostrarCofre, setMostrarTransportes, viagem 
}) => {
  const [data, setData] = useState('');
  const [hora, setHora] = useState('');
  const [local, setLocal] = useState('');
  const [notas, setNotas] = useState('');

  const [editItemId, setEditItemId] = useState(null);
  const [editData, setEditData] = useState('');
  const [editHora, setEditHora] = useState('');
  const [editLocal, setEditLocal] = useState('');
  const [editNotas, setEditNotas] = useState('');

  const viagemId = viagem ? viagem.id : null;
  const destino = viagem ? viagem.destino : null;

  const { itinerarios, criarItinerario, atualizarItinerario, apagarItinerario, carregarItinerarios } = useItinerario(viagemId);
  const { clima } = useClima(destino, mostrarItinerario);
  const { mostrarErro, mostrarSucesso } = useToast();

  const handleAdd = async () => {
    if (!data || !local || !viagemId) return;
    const result = await criarItinerario({
      viagem_id: parseInt(viagemId),
      data: data,
      hora: hora,
      local: local,
      notas: notas
    });
    if (result.sucesso) {
      setData('');
      setHora('');
      setLocal('');
      setNotas('');
      carregarItinerarios();
    } else {
      mostrarErro(MENSAGENS.ERRO_SERVIDOR);
    }
  };

  const handleDelete = async (uid) => {
    const result = await apagarItinerario(uid);
    if (result.sucesso) carregarItinerarios();
  };

  const iniciarEdicao = (item) => {
    setEditItemId(item.uid);
    const dataOriginal = item.data_hora ? item.data_hora.substring(0, 10) : '';
    const horaOriginal = item.data_hora ? item.data_hora.substring(11, 16) : '';
    
    setEditData(item.data || dataOriginal);
    setEditHora(item.hora || horaOriginal);
    setEditLocal(item.local || '');
    setEditNotas(item.notas || '');
  };

  const salvarEdicao = async (item) => {
    try {
      const dados = {
        uid: item.uid,
        viagem_id: parseInt(viagemId),
        local: editLocal,
        data: editData,
        hora: editHora,
        notas: editNotas
      };

      const result = await atualizarItinerario(dados);
      
      if (result && result.sucesso) {
        setEditItemId(null);
        carregarItinerarios();
        mostrarSucesso('Itinerário atualizado com sucesso!');
      } else {
        mostrarErro('Erro ao atualizar o itinerário.');
      }
    } catch (error) {
      mostrarErro(MENSAGENS.ERRO_COMUNICACAO);
    }
  };

  const itinerariosOrdenados = [...itinerarios].sort((a, b) => {
    const valA = a.data_hora || '';
    const valB = b.data_hora || '';
    if (!valA && !valB) return 0;
    if (!valA) return 1;
    if (!valB) return -1;
    const dateA = new Date(valA.replace(' ', 'T'));
    const dateB = new Date(valB.replace(' ', 'T'));
    return dateA - dateB;
  });

  const itinerariosAgrupados = itinerariosOrdenados.reduce((acc, item) => {
    const dataStr = item.data_hora ? item.data_hora.substring(0, 10) : 'Sem data';
    if (!acc[dataStr]) acc[dataStr] = [];
    acc[dataStr].push(item);
    return acc;
  }, {});

  const getDisplayHora = (item) => {
    const val = item.data_hora || '';
    if (!val) return '';
    return val.substring(11, 16);
  };

  return (
    <div className="card-viagem__membros-container" style={{ marginTop: '-10px' }}>
      <button
        type="button"
        className="card-viagem__membros-toggle"
        onClick={() => {
          setMostrarItinerario(!mostrarItinerario);
          setMostrarMembros(false);
          setMostrarAcertos(false);
          setMostrarChecklist(false);
          setMostrarMapa(false);
          setMostrarCofre(false);
          setMostrarTransportes(false);
        }}
      >
        <span>📍 Itinerário ({itinerarios.length})</span>
        <span>{mostrarItinerario ? '▲' : '▼'}</span>
      </button>

      {mostrarItinerario && (
        <div className="card-viagem__membros-content">
          <div className="card-viagem__checklist-lista" style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '16px' }}>
            {itinerariosOrdenados.length === 0 && <span className="card-viagem__membro-vazio">Nenhum local no itinerário.</span>}
            
            {Object.entries(itinerariosAgrupados).map(([dataStr, itens], index) => (
              <div key={dataStr} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingBottom: '4px', borderBottom: '2px solid #e2e8f0', marginTop: index > 0 ? '8px' : '0' }}>
                  <span style={{ fontWeight: 'bold', color: '#475569', fontSize: '0.95rem' }}>
                    {dataStr === 'Sem data' ? '📌 Sem data definida' : `📅 ${dataStr}`}
                  </span>
                  {clima[dataStr] && (
                    <span style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#64748b', display: 'flex', alignItems: 'center', gap: '4px' }}>
                      {clima[dataStr].icone} {Math.round(clima[dataStr].max)}° / {Math.round(clima[dataStr].min)}°
                    </span>
                  )}
                </div>
                
                {itens.map(i => (
                  <div key={i.uid} style={{ display: 'flex', gap: '12px', padding: '12px', backgroundColor: '#ffffff', border: '1px solid #e2e8f0', borderLeft: '4px solid #3b82f6', borderRadius: '8px', position: 'relative', boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
                    
                    {editItemId === i.uid ? (
                      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
                        <input 
                          type="text" 
                          value={editLocal} 
                          onChange={e => setEditLocal(e.target.value)} 
                          placeholder="Local (ex: Coliseu)"
                          style={{ padding: '6px', borderRadius: '6px', border: '1px solid #cbd5e1', fontWeight: '600', color: '#1e293b' }} 
                        />
                        
                        <div style={{ display: 'flex', gap: '8px' }}>
                          <input type="date" value={editData} onChange={e => setEditData(e.target.value)} style={{ flex: 1, padding: '6px', borderRadius: '6px', border: '1px solid #cbd5e1' }} />
                          <input type="time" value={editHora} onChange={e => setEditHora(e.target.value)} style={{ flex: 1, padding: '6px', borderRadius: '6px', border: '1px solid #cbd5e1' }} />
                        </div>
                        
                        {/* NOVO: Input para as Notas */}
                        <input 
                          type="text" 
                          value={editNotas} 
                          onChange={e => setEditNotas(e.target.value)} 
                          placeholder="Notas ou detalhes adicionais..."
                          style={{ padding: '6px', borderRadius: '6px', border: '1px solid #cbd5e1', fontSize: '0.85rem' }} 
                        />
                        
                        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', marginTop: '4px' }}>
                          <button onClick={() => setEditItemId(null)} style={{ background: '#f1f5f9', color: '#475569', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>Cancelar</button>
                          <button onClick={() => salvarEdicao(i)} style={{ background: '#3b82f6', color: '#fff', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>Guardar</button>
                        </div>
                      </div>
                    ) : (
                      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '6px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                          <span style={{ fontWeight: '600', color: '#1e293b', fontSize: '1rem' }}>{i.local}</span>
                          <div style={{ display: 'flex', gap: '10px' }}>
                            <button onClick={() => iniciarEdicao(i)} style={{ color: '#94a3b8', background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.1rem', padding: '0', lineHeight: '1' }}>✏️</button>
                            <button onClick={() => handleDelete(i.uid)} style={{ color: '#94a3b8', background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.1rem', padding: '0', lineHeight: '1' }}>✖</button>
                          </div>
                        </div>
                        {getDisplayHora(i) && (
                          <span style={{ fontSize: '0.85rem', color: '#3b82f6', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '6px' }}>
                            🕒 {getDisplayHora(i)}
                          </span>
                        )}
                        {i.notas && (
                          <span style={{ fontSize: '0.85rem', color: '#475569', backgroundColor: '#f8fafc', padding: '8px', borderRadius: '6px', border: '1px solid #f1f5f9', marginTop: '2px' }}>
                            📝 {i.notas}
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
          
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', backgroundColor: '#f8fafc', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
            <span style={{ fontSize: '0.9rem', fontWeight: '600', color: '#334155', marginBottom: '4px' }}>Adicionar Paragem Manual</span>
            <div style={{ display: 'flex', gap: '8px' }}>
              <input type="date" className="card-viagem__membros-input" value={data} onChange={e => setData(e.target.value)} style={{ flex: 1, backgroundColor: '#fff' }} />
              <input type="time" className="card-viagem__membros-input" value={hora} onChange={e => setHora(e.target.value)} style={{ flex: 1, backgroundColor: '#fff' }} />
            </div>
            <input type="text" className="card-viagem__membros-input" placeholder="Local (ex: Coliseu, Gare du Nord)" value={local} onChange={e => setLocal(e.target.value)} style={{ backgroundColor: '#fff' }} />
            <input type="text" className="card-viagem__membros-input" placeholder="Notas (opcional)" value={notas} onChange={e => setNotas(e.target.value)} style={{ backgroundColor: '#fff' }} />
            <button type="button" className="card-viagem__membros-btn" onClick={handleAdd} style={{ width: '100%', borderRadius: '6px', padding: '10px', marginTop: '4px', fontWeight: '600' }}>Adicionar ao Itinerário</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default SeccaoItinerario;